<?php require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/functions.php';$errors=[];$success='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$mobile=trim($_POST['mobile']??'');$pw=$_POST['password']??'';$course=trim($_POST['course']??'Computer Engineering');if(strlen($name)<2)$errors[]='Name must contain at least two characters.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if(!preg_match('/^[6-9][0-9]{9}$/',$mobile))$errors[]='Enter a valid 10-digit Indian mobile number.';if(strlen($pw)<8)$errors[]='Password must be at least eight characters.';if(!$errors){$check=$conn->prepare('SELECT id FROM users WHERE email=?');$check->bind_param('s',$email);$check->execute();$check->store_result();if($check->num_rows)$errors[]='An account with this email already exists.';$check->close();}if(!$errors){$hash=password_hash($pw,PASSWORD_DEFAULT);$role='student';$s=$conn->prepare('INSERT INTO users(name,email,mobile,password_hash,role,course) VALUES(?,?,?,?,?,?)');$s->bind_param('ssssss',$name,$email,$mobile,$hash,$role,$course);if($s->execute()){$success='Registration successful. You can now sign in.';audit($conn,'user.register','New account: '.$email);}else $errors[]='Registration could not be completed.';$s->close();}}
$pageTitle='Register | StudentHub';require __DIR__.'/../includes/header.php'; ?><span class="eyebrow">Create an account</span><h1>Join StudentHub</h1><?php foreach($errors as $er): ?><p class="error notice"><?= e($er) ?></p><?php endforeach;if($success): ?><p class="success"><?= e($success) ?> <a href="login.php">Sign in</a></p><?php endif; ?><form id="registrationForm" class="form" method="post" novalidate><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="form-grid"><div class="field"><label for="name">Full name</label><input id="name" name="name" required minlength="2" autocomplete="name"><small id="nameError" class="error"></small></div><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" required autocomplete="email"><small id="emailError" class="error"></small></div><div class="field"><label for="mobile">Mobile number</label><input id="mobile" name="mobile" inputmode="numeric" required maxlength="10"><small id="mobileError" class="error"></small></div><div class="field"><label for="course">Course</label><select id="course" name="course"><option>Computer Engineering</option><option>Information Technology</option><option>Electronics</option><option>Mechanical Engineering</option></select></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" required minlength="8" autocomplete="new-password"><small>Password strength: <span id="strengthText">Not entered</span></small><small id="passwordError" class="error"></small></div><div class="field"><label for="confirm_password">Confirm password</label><input id="confirm_password" name="confirm_password" type="password" required autocomplete="new-password"><small id="confirmError" class="error"></small></div><div class="field full"><label><input type="checkbox" name="terms" required style="width:auto"> I agree to the demo portal terms.</label><small id="termsError" class="error"></small></div></div><button class="button">Create account</button><p>Already registered? <a href="login.php">Sign in</a></p></form><?php require __DIR__.'/../includes/footer.php'; ?>
